from collections import defaultdict

class TimeMap:

    def __init__(self):
        self.hashmap = defaultdict(list)

    def set(self, key: str, value: str, timestamp: int) -> None:
        self.hashmap[key].append((timestamp, value))

    def get(self, key: str, timestamp: int) -> str:

        time_value_list = self.hashmap[key]

        if not time_value_list or timestamp < time_value_list[0][0]:
            return ""

        left = 0
        right = len(time_value_list)-1

        while(left <= right):
            mid = (left + right)//2

            midk, val = time_value_list[mid]

            if midk == timestamp:
                return val

            elif timestamp > midk:
                left = mid + 1

            else:
                right = mid - 1


        return time_value_list[right][1]

