class Solution:
    def slidingPuzzle(self, board: List[List[int]]) -> int:
        rows = 2
        cols = 3


        def is_valid(x, y):
            return (0 <= x < rows) and (0 <= y < cols)

        def get_state(board):
            return tuple([tuple(x) for x in board])

        def get_neighbours(x, y, state):
            neighbours = []
            zero_pos = []
            state = [list(x) for x in state]

            for dx, dy in ((0, 1), (1, 0), (0, -1), (-1, 0)):
                nx, ny = x+dx, y+dy
                if is_valid(nx, ny):
                    state[x][y], state[nx][ny] = state[nx][ny], state[x][y]
                    neighbours.append(get_state(state))
                    zero_pos.append((nx, ny))
                    state[x][y], state[nx][ny] = state[nx][ny], state[x][y]
            return neighbours, zero_pos

        def bfs(x, y):
            moves = 0
            start = get_state(board)
            q = deque()
            q.append((x, y, start))

            visited = set()
            visited.add(start)

            while q:
                n = len(q)
                for _ in range(n):
                    i, j, state = q.popleft()
                    if state == desired:
                        return moves


                    neighbours, zero_positions = get_neighbours(i, j, state)
                    for nstate, (nx, ny) in zip(neighbours, zero_positions):
                        if nstate not in visited:
                            q.append((nx, ny, nstate))
                            visited.add(nstate)
                moves+=1
            return -1

        desired = ((1,2,3),(4,5,0))
        for i in range(2):
            for j in range(3):
                if board[i][j] == 0:
                    return bfs(i, j)

