from typing import *
from collections import deque
class Solution:
    def openLock(self, deadends: List[str], target: str) -> int:

        def get_neighbours(state):
            state = [int(x) for x in state]
            neighbours = []

            for i in range(4):
                ori = state[i]
                incre = (ori+1)%10
                decre = (ori-1)%10

                for change in [incre, decre]:
                    state[i] = change
                    neighbours.append("".join([str(x) for x in state]))

                state[i] = ori
            return neighbours

        q = deque()
        q.append(["0000"])
        seen = set(["0000"])
        deadends = set(deadends)
        moves = 0
        found = False
        while q:
            level = q.popleft()
            if target in level:
                found = True
                break
            moves += 1
            next_level = []
            for node in level:
                if node not in deadends:
                    for child in get_neighbours(node):
                        if child not in seen:
                            seen.add(child)
                            next_level.append(child)
            if next_level:
                q.append(next_level)

        if found:
            return moves
        else:
            return -1

