class Solution:
    def dailyTemperatures(self, temperatures: List[int]) -> List[int]:
        stack = deque()

        answer = [0] * len(temperatures)

        for idx, temp in enumerate(temperatures):
            while(stack and temp > stack[-1][1]):
                st_idx = stack[-1][0]

                answer[st_idx] = idx-st_idx

                stack.pop()

            stack.append((idx, temp))

        return answer

