import java.util.Random;

class RandomizedSet {
  private HashMap<Integer, Integer> map = null;
  private ArrayList<Integer> list = null;
  private Random random = null;

  public RandomizedSet() {
    map = new HashMap<>();
    list = new ArrayList<>();
    random = new Random();
  }

  public boolean insert(int val) {
    if (map.containsKey(val)) {
      return false;
    }
    map.put(val, list.size());
    list.add(val);
    return true;
  }

  public boolean remove(int val) {
    if (map.containsKey(val)) {
      int listIdx = map.get(val);
      map.remove(val);

      int n = list.size();
      int lastElement = list.get(n - 1);

      if (listIdx != n-1) {
        map.put(lastElement, listIdx);
        list.set(listIdx, lastElement);
      }
      list.remove(n-1);

      return true;
    }
    return false;
  }

  public int getRandom() {
    int randomIdx = random.nextInt(list.size());
    return list.get(randomIdx);
  }
}

