class Solution:
    def coinChange(self, coins: List[int], amount: int) -> int:

        memo = {}

        def dfs(remaining):
            if remaining == 0:
                return 0
            if remaining < 0:
                return float('inf')

            if remaining in memo:
                return memo[remaining]

            min_coins = float('inf')
            for coin in coins:
                res = dfs(remaining - coin)
                if res != float('inf'):
                    min_coins = min(min_coins, res + 1)

            memo[remaining] = min_coins
            return min_coins

        res = dfs(amount)
        return -1 if res == float('inf') else res

