class Solution {
  public int[] productExceptSelf(int[] nums) {
    int n = nums.length;

    int leftToRight[] = new int[n];
    int runningProduct = 1;
    for (int i = 0; i < n; i++) {
      leftToRight[i] = runningProduct;
      runningProduct *= nums[i];
    }

    int productExceptSelf[] = new int[n];
    runningProduct = 1;
    for (int i = n-1; i >= 0; i--) {
      productExceptSelf[i] = leftToRight[i] * runningProduct;
      runningProduct *= nums[i];
    }

    return productExceptSelf;
  }

  public static void main(String[] args) {
    int nums[] = { 1, 2, 3, 4 };
    int nums2[] = { -1, 1, 0, -3, 3 };
    int ans[] = new Solution().productExceptSelf(nums);
    int ans2[] = new Solution().productExceptSelf(nums2);
    for (int i : ans) {
      System.out.print(i + " ");
    }
    System.out.println();
    for (int i : ans2) {
      System.out.print(i + " ");
    }
  }
}

