    def findMin(self, nums: List[int]) -> int:
        left = 0
        right = len(nums)-1

        while left <= right:

            mid = (left + right)//2

            mid_num = nums[mid]

            prev_num = nums[mid-1] if mid > 0 else float("inf")
            next_num = nums[mid+1] if mid != len(nums)-1 else float("inf")

            if mid_num < prev_num or mid_num > next_num:
                return min([prev_num, mid_num, next_num])

            left_num = nums[left]
            right_num = nums[right]

            if left_num > mid_num:
                right = mid-1
            elif mid_num > right_num:
                left = mid+1
            else:
                return nums[0]

            left, right = 0, len(nums)-1

    def findMin(self, nums: List[int]) -> int:
        left = 0
        right = len(nums)-1
        while(nums[left] > nums[right]):
            mid = (left + right) // 2

            if nums[mid] > nums[right]:
                left = mid + 1
            else:
                right = mid

        return nums[left]

