class Solution:
    def minDepth(self, root: Optional[TreeNode]) -> int:
        q = deque()
        if root:
            q.append([root])
        depth = 0
        while len(q)>0:
            depth += 1
            level = q.popleft()
            next_level = []
            for node in level:
                children = [node.left, node.right]

                if all(child is None for child in children):
                    return depth

                for child in children:
                    if child:
                        next_level.append(child)
            if next_level:
                q.append(next_level)
        return depth

