class Solution:
    def deleteDuplicates(self, head: Optional[ListNode]) -> Optional[ListNode]:
        if head is None or head.next is None:
            return head

        dummy = ListNode(0, None)
        ptr = dummy

        temp = head
        while temp is not None:
            next_node = temp.next
            isdup = False

            while next_node and next_node.val == temp.val:
                next_node = next_node.next
                isdup = True

            if isdup:
                temp = next_node
            else:
                ptr.next = temp
                ptr = temp
                temp = temp.next

        if isdup:
            ptr.next = None 

        return dummy.next

