from typing import *
class Solution:
    def exist(self, board: List[List[str]], word: str) -> bool:
        rows = len(board)
        cols = len(board[0])
        used = set()

        def isValidPos(x, y):
            return (x < rows and y < cols) and \
                    (x > -1 and y > -1)

        def dfs(x, y, index):

            if index == len(word):
                return True

            if not isValidPos(x, y):
                return False

            if (x, y) in used:
                return False

            if board[x][y] != word[index]:
                return False

            used.add((x, y))

            ans = (
                dfs(x, y+1, index+1) or
                dfs(x-1, y, index+1) or
                dfs(x, y-1, index+1) or
                dfs(x+1, y, index+1)
            )

            used.remove((x, y))

            return ans

        for i in range(rows):
            for j in range(cols):
                if dfs(i, j, 0):
                    return True
        return False

