class Solution:
    def minPathSum(self, grid: List[List[int]]) -> int:
        rows = len(grid)
        cols = len(grid[0])

        def isValidPos(x, y):
            return x<rows and y<cols

        memo = dict()
        def dfs(x, y, total):
            if x == rows-1 and y == cols-1:
                return total+grid[x][y]

            if not isValidPos(x, y):
                return float("inf")

            try:
                return total+memo[(x,y)]
            except KeyError:
                pass

            ans = min(
                dfs(x, y+1, total+grid[x][y]),
                dfs(x+1, y, total+grid[x][y])
            )

            memo[(x,y)] = ans-total
            return ans

        return dfs(0, 0, 0)

