class Solution:
    def rotateRight(self, head: Optional[ListNode], k: int) -> Optional[ListNode]:
        if not head:
            return head

        nodes = 1
        tail = head

        while tail.next is not None:
            nodes += 1
            tail = tail.next

        k = k % nodes
        if k == 0:
            return head

        new_tail = head
        for _ in range(nodes - k - 1):
