    def insert(
        self, intervals: List[List[int]], newInterval: List[int]
    ) -> List[List[int]]:
        def merge():
            output = list()
            idx = 0
            while idx < len(intervals):
                a, b = intervals[idx]
                nxt = idx + 1
                while nxt < len(intervals) and intervals[nxt][0] <= b:
                    b = max(b, intervals[nxt][1])
                    nxt += 1

                output.append([a, b])
                idx = nxt

            return output

        idx = 0
        while idx < len(intervals) and newInterval[0] >= intervals[idx][0]:
            idx += 1

        intervals.insert(idx, newInterval)
