class Solution:
    def binary_search(self, left, right, nums, target):
        while left <= right:
            mid = (left+right)//2
            if nums[mid] == target:
                return mid
            elif target < nums[mid]:
                right = mid-1
            else:
                left = mid+1
        return -1

    def searchRange(self, nums: List[int], target: int) -> List[int]:
        left = 0
        right = len(nums)-1

        def solve(left, right, prev_find, search_direction):
            find = self.binary_search(left, right, nums, target)

            if find == -1:
                return prev_find

            if search_direction == "left":
                return solve(left, find-1, find, search_direction)
            else:
                return solve(find+1, right, find, search_direction)

        ans = [
                solve(left, right, -1, "left"),
                solve(left, right, -1, "right")
            ]

        return ans

