class Solution:
    def reverseKGroup(self, head: Optional[ListNode], k: int) -> Optional[ListNode]:
        if not head or head.next is None:
            return head

        def get_len():
            temp = head
            count = 0

            while temp is not None:
                count += 1
                temp = temp.next

            return count

        def reverseLL(start):
            new_head = start

            for _ in range(k-1):
                next_node = start.next
                start.next = start.next.next
                next_node.next = new_head
                new_head = next_node

            return new_head

        nodes = get_len()
        groups = nodes // k
        dummy = ListNode(0, head)
        temp = dummy
        for _ in range(groups):
            temp.next = reverseLL(temp.next)
            for __ in range(k):
                temp = temp.next

        return dummy.next

