    def isValid(self, s: str) -> bool:
        stack = list()

        for ch in s:
            if ch in "({[":
                stack.append(ch)
                continue

            if not stack:
                return False

            top = stack[-1]
            if (
                (top == "(" and ch != ")")
                or (top == "{" and ch != "}")
                or (top == "[" and ch != "]")
            ):
                return False
            else:
                stack.pop()

