class Solution:
    def threeSum(self, nums: List[int]) -> List[List[int]]:
        nums.sort()
        answers = list()

        for i in range(len(nums)):
            target = nums[i]

            if target > 1:
                break

            if i > 0 and nums[i - 1] == nums[i]:
                continue

            left = i + 1
            right = len(nums) - 1

            while left < right:
                total = nums[left] + nums[right]

                if total == -target:
                    answers.append([target, nums[left], nums[right]])
                    left += 1
                    while left < right and nums[left - 1] == nums[left]:
                        left += 1

                elif total < -target:
                    left += 1

                else:
                    right -= 1

        return answers


