        array = []
        for _ in range(numRows):
            array.append([])

        k = 0
        incre = 1
        for i in range(len(s)):
            array[k].append(s[i])

            if incre == 1 and k == numRows - 1:
                incre = -1

            if incre == -1 and k == 0:
                incre = 1

            if numRows > 1:
                k += incre

        ans = []
        for row in array:
            ans.append("".join(row))

        return "".join(ans)


